"""Generated by solo-to-scale; edit `templates/tools/finance.py` in the plugin, then run upgrade.

Money: revenue, costs, burn and runway, from founder/finance.json (founder-owned; the `spend` gate) and this
month's AI spend from the cost log.

  python tools/finance.py show [--ai-usd X]   # MRR, monthly costs, net burn, runway, AI share of costs
  python tools/finance.py check               # exit 1 when finance.json is malformed

Monthly costs are the fixed costs plus AI spend (the month-end forecast when there is one). Net burn is monthly
costs minus monthly revenue. Runway is cash divided by net burn; with no burn the company is not spending its cash.
One-off items count in the month they fall in and lower the cash left, not the monthly burn.
Python 3 standard library only.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402

TEMPLATE = {
    "about": "Money for the dashboard's runway. Only the founder edits this file (the spend gate). Amounts are per "
             "month in the currency named here; null means not set. cash: money in the bank on as_of (YYYY-MM-DD). "
             "fixed_costs: recurring monthly costs such as tools, hosting and ads; AI spend comes from the cost log. "
             "one_offs: single payments in a month (YYYY-MM), positive for a cost, negative for money in.",
    "currency": "USD", "cash": None, "as_of": "", "monthly_revenue": None, "fixed_costs": [], "one_offs": []}


def num(v: Any) -> float | None:
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else None


def load(root: Path = s.ROOT) -> dict[str, Any] | None:
    raw = s.read(root / "founder" / "finance.json")
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except ValueError:
        return {"_broken": "not valid JSON"}
    return data if isinstance(data, dict) else {"_broken": "not a JSON object"}


def problems(data: dict[str, Any] | None) -> list[str]:
    if data is None:
        return []
    if data.get("_broken"):
        return [f"founder/finance.json is {data['_broken']}"]
    out = []
    for k in ("cash", "monthly_revenue"):
        if data.get(k) is not None and num(data.get(k)) is None:
            out.append(f"{k} must be a number or null")
    for k, need in (("fixed_costs", ("name", "monthly")), ("one_offs", ("name", "amount", "month"))):
        rows = data.get(k) or []
        if not isinstance(rows, list):
            out.append(f"{k} must be a list")
            continue
        for i, r in enumerate(rows):
            if not isinstance(r, dict) or any(f not in r for f in need):
                out.append(f"{k}[{i}] needs {', '.join(need)}")
            elif num(r.get(need[1])) is None:
                out.append(f"{k}[{i}].{need[1]} must be a number")
    return out


def summary(data: dict[str, Any] | None, ai_usd: float, month: str) -> dict[str, Any]:
    """The money panel: everything the Overview shows, or set False when the founder hasn't filled the file in."""
    if not data or data.get("_broken") or problems(data):
        return {"set": False, "problems": problems(data), "ai": round(ai_usd, 2), "month": month}
    fixed_rows = [{"name": str(r.get("name", ""))[:80], "monthly": num(r.get("monthly")) or 0.0}
                  for r in data.get("fixed_costs") or []]
    fixed = sum(r["monthly"] for r in fixed_rows)
    mrr = num(data.get("monthly_revenue"))
    cash = num(data.get("cash"))
    once = [{"name": str(r.get("name", ""))[:80], "amount": num(r.get("amount")) or 0.0, "month": str(r.get("month", ""))}
            for r in data.get("one_offs") or []]
    this_month = sum(r["amount"] for r in once if r["month"] == month)
    costs = fixed + ai_usd
    burn = costs - (mrr or 0.0)
    left = cash - this_month if cash is not None else None
    runway = None if left is None or burn <= 0 else max(left, 0.0) / burn
    return {"set": cash is not None or mrr is not None or bool(fixed_rows), "currency": str(data.get("currency") or "USD")[:8],
            "as_of": str(data.get("as_of") or ""), "month": month, "cash": cash, "mrr": mrr, "fixed": round(fixed, 2),
            "fixed_costs": fixed_rows, "ai": round(ai_usd, 2), "costs": round(costs, 2), "net_burn": round(burn, 2),
            "one_offs": [r for r in once if r["month"] == month], "one_offs_total": round(this_month, 2),
            "cash_left": round(left, 2) if left is not None else None,
            "runway_months": round(runway, 1) if runway is not None else None,
            "profitable": burn <= 0 and mrr is not None,
            "ai_share": round(ai_usd / costs, 3) if costs > 0 else None, "problems": []}


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT)
    sub = p.add_subparsers(dest="cmd", required=True)
    sh = sub.add_parser("show", parents=[common])
    sh.add_argument("--ai-usd", type=float, default=0.0, help="this month's AI spend (heartbeat.py costs prints it)")
    sh.add_argument("--month", default="")
    sub.add_parser("check", parents=[common])
    a = p.parse_args(argv)
    data = load(a.root)
    if a.cmd == "check":
        found = problems(data)
        for f in found:
            print(f"finance: {f}")
        if not found:
            print("finance: OK")
        return 1 if found else 0
    import datetime as dt
    month = a.month or dt.datetime.now(dt.timezone.utc).strftime("%Y-%m")
    m = summary(data, a.ai_usd, month)
    if not m["set"]:
        print("founder/finance.json isn't filled in: " + ("; ".join(m["problems"]) or "set cash, monthly_revenue and fixed_costs"))
        return 0
    cur = m["currency"]
    print(f"MRR: {m['mrr'] if m['mrr'] is not None else 'not set'} {cur}")
    print(f"monthly costs: {m['costs']:.2f} {cur} (fixed {m['fixed']:.2f}, AI {m['ai']:.2f}"
          + (f", AI is {m['ai_share']:.0%} of costs" if m["ai_share"] is not None else "") + ")")
    print(f"net burn: {m['net_burn']:.2f} {cur} a month")
    if m["one_offs"]:
        print(f"one-offs in {month}: {m['one_offs_total']:.2f} {cur}")
    print("runway: " + ("not burning cash" if m["runway_months"] is None and m["net_burn"] <= 0 else
                        f"{m['runway_months']} months" if m["runway_months"] is not None else "set cash to see it"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
